package android.os;import java.util.*;public class Handler {private static final Queue<Runnable> pending=new ArrayDeque<Runnable>();public static int posted;public Handler(){}public Handler(Looper l){}public boolean post(Runnable r){synchronized(pending){pending.add(r);posted++;}return true;}public boolean postDelayed(Runnable r,long d){return post(r);}public void removeCallbacks(Runnable r){synchronized(pending){pending.remove(r);}}public static void dispatchAll(){for(int i=0;i<10000;i++){Runnable r;synchronized(pending){r=pending.poll();}if(r==null)return;r.run();}throw new AssertionError("unbounded Handler work");}public static void reset(){synchronized(pending){pending.clear();posted=0;}}}
